// The native Android project is generated by `npx cap add android` in CI,
// so versioned permission changes must be applied after Capacitor sync.
// No generated Android project files or user data are committed.
import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { resolve, join, dirname } from 'node:path';

const root = resolve('android/app/src/main');
const manifestPath = join(root, 'AndroidManifest.xml');
const original = await readFile(manifestPath, 'utf8');
let manifest = original;
if (!manifest.includes('android.permission.CAMERA')) {
  manifest = manifest.replace('</manifest>',
    '    <uses-permission android:name="android.permission.CAMERA" />\n' +
    '    <uses-feature android:name="android.hardware.camera.any" android:required="false" />\n' +
    '</manifest>');
}
if (!manifest.includes('android.permission.CAMERA') || !manifest.includes('</manifest>')) {
  throw new Error('Failed to declare Android camera permission safely');
}
if (manifest !== original) await writeFile(manifestPath, manifest);

const javaRoot = join(root, 'java');
async function findMainActivity(path) {
  const entries = await readdir(path, { withFileTypes: true });
  for (const entry of entries) {
    const full = join(path, entry.name);
    if (entry.isDirectory()) {
      const found = await findMainActivity(full);
      if (found) return found;
    } else if (entry.name === 'MainActivity.java') {
      const source = await readFile(full, 'utf8');
      if (source.includes('extends BridgeActivity')) return { path: full, source };
    }
  }
  return null;
}
const main = await findMainActivity(javaRoot);
if (!main) throw new Error('No generated Capacitor BridgeActivity found');

const match = main.source.match(/^package\s+([a-zA-Z_][\w]*(?:\.[a-zA-Z_][\w]*)*)\s*;/m);
if (!match) throw new Error('Cannot determine generated Android application package');
const packageName = match[1];
if (packageName !== 'africa.orvix.app') throw new Error('Unexpected Android app package: ' + packageName);
const pluginPath = join(dirname(main.path), 'OrvixCameraPermissions.java');
const template = await readFile(resolve('scripts/native-android-camera/OrvixCameraPermissions.java'), 'utf8');
await mkdir(dirname(pluginPath), { recursive: true });
await writeFile(pluginPath, template.replace('__ORVIX_PACKAGE__', packageName));

const marker = 'registerPlugin(OrvixCameraPermissions.class);';
let activity = main.source;
if (!activity.includes(marker)) {
  const classMarker = /public\s+class\s+MainActivity\s+extends\s+BridgeActivity\s*\{/;
  if (!classMarker.test(activity) || /void\s+onCreate\s*\(/.test(activity)) {
    throw new Error('Generated MainActivity changed: refusing to replace unknown camera lifecycle');
  }
  activity = activity.replace(classMarker,
    'public class MainActivity extends BridgeActivity {\n' +
    '  @Override\n' +
    '  public void onCreate(android.os.Bundle savedInstanceState) {\n' +
    '    ' + marker + '\n' +
    '    super.onCreate(savedInstanceState);\n' +
    '  }\n');
  await writeFile(main.path, activity);
}
if (!activity.includes(marker)) throw new Error('Camera permission plugin not registered');
console.log('Orvix camera permission recovery installed for ' + packageName);
